-- Expected source rows: 322. Store-only import; equipment stays separate.

begin;

insert into public.gym_chains (id,name,search_aliases)
select id,name,search_aliases
from jsonb_to_recordset('[{"id":"fit-easy","name":"FIT-EASY","search_aliases":["フィットイージー","FITEASY"]}]'::jsonb)
  as r(id text,name text,search_aliases text[])
on conflict (id) do update set
  name=excluded.name,
  search_aliases=excluded.search_aliases,
  updated_at=now();

